/* Kill-switch service worker (2026-08-29).
 * PWA 를 끄기 전(빌드 #143 이하)에 설치된 Chirpy 서비스워커가 옛 사이트를
 * 캐시로 계속 서빙했다. 브라우저는 내비게이션 때 이 URL 의 새 버전을 다시
 * 받아오므로, 여기서 캐시를 비우고 스스로 등록 해제한 뒤 열린 탭을 새로고침한다.
 * 모든 방문자가 한 번씩 거쳐 가도록 당분간 유지할 것 (제거는 수개월 뒤 권장).
 */
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    (async function () {
      try {
        const keys = await caches.keys();
        await Promise.all(keys.map(function (k) { return caches.delete(k); }));
      } catch (e) { /* noop */ }
      try {
        await self.registration.unregister();
      } catch (e) { /* noop */ }
      try {
        const clients = await self.clients.matchAll({ type: 'window' });
        clients.forEach(function (c) { c.navigate(c.url); });
      } catch (e) { /* noop */ }
    })()
  );
});
